// The building blocks of the class registrations of batch C1 (phase 5a, docs/DECOMPILATION.md 10, "Batch C1"):
// the startup registration stubs (classreg_a-d.cpp), the class info getters (classreg_getters.cpp, the
// per-variable registrations in classreg_vars.h, generated by tools/gen_classreg.py) and the hand-written
// functions that begin with a getter (classreg_slots.cpp). Every exe function is called through its exe
// address, so Disable= and the checks' stand-ins apply. The helpers take the addresses as keys of the address layer
// (batch 6-7, docs/DECOMPILATION.md 13): the generated modules spell them as plain literals, which stay constants.
#pragma once
#include "reimpl.h"

namespace zax::classreg {

// ClassInfo_StaticRegister 0x417690 (thiscall object, getter): ClassRegistry_Add(ClassRegistry_Get(), getter(), 0);
// returns the object
inline DWORD static_register(GlobKey object, CodeKey getter)
{
    return fn<DWORD(THISCALL *)(void *, DWORD)>(0x417690)(glob<void *>(object), key_fn_addr(getter));
}

// The registration a getter inlines: if the class variable is 0, a class info from the pool (operator_new_ecx
// 0x417710, 0x48 bytes) and, when the pool gave one, the parent (computed after the allocation, as the exe
// does) and ClassInfo_Register 0x415780 (thiscall class info, var, name, version as float bits, parent, size,
// abstract, create, create array, register fields; its eax is not used). eax: the variable. `ran` (for the
// hand-written functions whose exits differ) tells whether ClassInfo_Register was called.
using Parent = DWORD(__cdecl *)();
inline DWORD class_reg(GlobKey var, GlobKey name, DWORD version, Parent parent, DWORD size, DWORD abstract, CodeKey create,
                       CodeKey create_array, CodeKey register_fields, bool *ran = nullptr)
{
    DWORD &v = *glob<DWORD *>(var);
    if (ran)
        *ran = false;
    if (!v)
        if (void *p = fn<void *(__fastcall *)(DWORD)>(0x417710)(0x48)) {
            fn<DWORD(THISCALL *)(void *, DWORD, DWORD, DWORD, DWORD, DWORD, DWORD, DWORD, DWORD, DWORD)>(0x415780)(
                p, key_glob_addr(var), key_glob_addr(name), version, parent(), size, abstract, key_fn_addr(create),
                key_fn_addr(create_array), key_fn_addr(register_fields));
            if (ran)
                *ran = true;
        }
    return v;
}
// The parent as an immediate (0 or -1 for the classes without a parent)
template <DWORD V> DWORD __cdecl konst() { return V; }
// The parent's getter called through its exe address
template <DWORD A> DWORD __cdecl exe_getter() { return fn<DWORD(__cdecl *)()>(A)(); }

// ClassRegistry_Add(ClassRegistry_Get(), class, 0) (0x415a20 thiscall registry, class, flag; 0x415d20 cdecl):
// the static registration with the getter inlined; eax Add's
inline DWORD registry_add(DWORD cls)
{
    void *registry = fn<void *(__cdecl *)()>(0x415d20)();
    return fn<DWORD(THISCALL *)(void *, DWORD, DWORD)>(0x415a20)(registry, cls, 0);
}

}  // namespace zax::classreg

namespace zax {
using classreg::static_register;
}
